#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"; source "${SCRIPT_DIR}/lib/common.sh"; source "${SCRIPT_DIR}/lib/config.sh"; source "${SCRIPT_DIR}/lib/overview.sh"
OVERVIEW="" FORMAT=both; for arg in "$@"; do case "${arg}" in --overview=*) OVERVIEW="${arg#*=}";; --yyyymmdd=*) YYYYMMDD="${arg#*=}";; --workdir=*) WORKDIR="${arg#*=}";; --format=*) FORMAT="${arg#*=}";; -h|--help) printf 'usage: %s --overview=<id> [--yyyymmdd=YYYYMMDD] [--format=tar|zip|both] [--workdir=<path>]\n' "$0"; exit 0;; *) die "${HUAVD_EXIT_INPUT}" "unknown argument: ${arg}";; esac; done
[[ -n "${OVERVIEW}" ]] || die "${HUAVD_EXIT_INPUT}" "--overview is required"; validate_yyyymmdd "${YYYYMMDD}"; [[ "${FORMAT}" =~ ^(tar|zip|both)$ ]] || die "${HUAVD_EXIT_INPUT}" "invalid format"; require_cmd tar zip; overview_validate "${OVERVIEW}"
pack="$(pack_cache_dir)/overviews/$(overview_session "${OVERVIEW}" "${YYYYMMDD}")"; rm -rf "${pack}"; ensure_dir "${pack}"; for file in "$(overview_pmtiles_path "${OVERVIEW}" "${YYYYMMDD}")" "$(overview_sha512_path "${OVERVIEW}" "${YYYYMMDD}")" "$(overview_manifest_path "${OVERVIEW}" "${YYYYMMDD}")" "$(overview_attribution_path "${OVERVIEW}" "${YYYYMMDD}")"; do require_file "${file}"; cp "${file}" "${pack}/"; done
write_checksum_manifest "${pack}" SHA256SUMS sha256; out="$(outputs_dir)"; stem="$(overview_stem "${OVERVIEW}" "${YYYYMMDD}")"; [[ "${FORMAT}" == tar || "${FORMAT}" == both ]] && { tar -C "${pack}" -czf "${out}/${stem}.bundle.tar.gz" .; write_sha512_file "${out}/${stem}.bundle.tar.gz"; }; [[ "${FORMAT}" == zip || "${FORMAT}" == both ]] && { rm -f "${out}/${stem}.bundle.zip"; (cd "${pack}" && zip -qr "${out}/${stem}.bundle.zip" .); write_sha512_file "${out}/${stem}.bundle.zip"; }
